{"id":"44530504","title":"Password confirmation in Rails 5","body":"<p>This is my view:</p>

<pre><code>&lt;%=form_for [:admin, @user] do |f|%&gt;

    &lt;ul&gt;
        &lt;% @user.errors.full_messages.each do |msg| %&gt;
            &lt;li&gt;&lt;%= msg %&gt;&lt;/li&gt;
        &lt;% end %&gt;
    &lt;/ul&gt;

    &lt;%=f.label :name %&gt;
    &lt;%=f.text_field :name %&gt;


    &lt;%=f.label :email %&gt;
    &lt;%=f.text_field :email %&gt;

    &lt;%=f.label :password %&gt;
    &lt;%=f.password_field :password %&gt;

    &lt;%=f.label :password_confirmation %&gt;
    &lt;%=f.password_field :password_confirmation%&gt;

    &lt;%=f.submit "Submit" %&gt;
&lt;%end%&gt;
